using System;
using System.Collections.Generic;
using System.Linq;

namespace ET.Server
{
    [EntitySystemOf(typeof(OnlineWorldComponent))]
    [FriendOf(typeof(OnlineWorldComponent))]
    public static partial class OnlineWorldComponentSystem
    {
        [EntitySystem]
        private static void Awake(this OnlineWorldComponent self)
        {
            long now = TimeInfo.Instance.ServerNow();
            self.LastInvalidInputLogAt = now;
            Options options = Options.Instance;
            self.TickMilliseconds = Math.Max(10, options.OnlineWorldTickMilliseconds);
            self.PlayerRespawnMilliseconds = Math.Max(50, options.OnlineWorldPlayerRespawnMilliseconds);
            self.NavigationHeartbeatMilliseconds = Math.Max(20, options.OnlineWorldNavigationHeartbeatMilliseconds);
            self.NavigationLeaseTimeoutMilliseconds = Math.Max(50, options.OnlineWorldNavigationLeaseTimeoutMilliseconds);
            self.CorpseLifetimeMilliseconds = options.OnlineWorldCorpseLifetimeMillisecondsOverride > 0
                ? options.OnlineWorldCorpseLifetimeMillisecondsOverride
                : checked(ServerConfig.Instance.OnlineWorldRule.CorpseLifetimeSeconds * 1000);
            self.DropLeaveCommitResponseCount = Math.Max(0, options.OnlineWorldDropLeaveCommitResponseCount);
            if (options.OnlineWorldCorpseLifetimeMillisecondsOverride > 0)
                Log.Warning($"online world corpse lifetime override enabled milliseconds={self.CorpseLifetimeMilliseconds}");
            if (self.DropLeaveCommitResponseCount > 0)
                Log.Warning($"online world leave commit response injection enabled count={self.DropLeaveCommitResponseCount}");
            if (self.NavigationLeaseTimeoutMilliseconds <= self.NavigationHeartbeatMilliseconds)
                throw new Exception("OnlineWorldNavigationLeaseTimeoutMilliseconds must be greater than heartbeat interval.");
            foreach (string mapId in ServerConfig.Instance.OnlineWorldMapIds)
            {
                if (!ServerConfig.Instance.TryGetOnlineWorldPlayerSpawn(mapId, out MapSpawnConfig spawn))
                    throw new Exception($"Online World player spawn missing: mapId={mapId}");
                self.MapStates.Add(mapId, new OnlineWorldMapState
                {
                    MapId = mapId, PlayerSpawn = spawn, PlayerConfig = ServerConfig.Instance.GetPlayer(spawn.ConfigId),
                    LastNavigationHeartbeatAt = now
                });
            }
            OnlineWorldMapState main = self.RequireMap(OnlineWorldComponent.MainMapId);
            foreach (MapSpawnConfig spawn in ServerConfig.Instance.MainWorldEnemySpawns)
            {
                long id = self.AllocateUnitId(); EnemyConfig config = ServerConfig.Instance.GetEnemy(spawn.ConfigId);
                main.Enemies.Add(id, new OnlineWorldEnemy
                {
                    UnitId=id,WorldId=self.WorldId,MapId=main.MapId,EnemyConfigId=config.Id,Config=config,
                    SpawnPositionX=spawn.PositionX,SpawnPositionY=spawn.PositionY,SpawnPositionZ=spawn.PositionZ,
                    SpawnYawDegrees=spawn.RotationY,PositionX=spawn.PositionX,PositionY=spawn.PositionY,
                    PositionZ=spawn.PositionZ,YawDegrees=spawn.RotationY,CurrentHP=config.MaxHP,MaxHP=config.MaxHP,
                    StateRevision=1,LifecycleRevision=1,LastNavigationAt=now
                });
            }
            int generation = ++self.TickGeneration; TickLoop(self, generation).Coroutine();
        }

        [EntitySystem] private static void Destroy(this OnlineWorldComponent self) {self.TickGeneration++;foreach(var state in self.MapStates.Values)state.Projectiles.Clear();}
        public static long AllocateUnitId(this OnlineWorldComponent self)
        { if(self.NextUnitId<1||self.NextUnitId>int.MaxValue)throw new InvalidOperationException("Online World UnitId exhausted.");return self.NextUnitId++; }
        private static OnlineWorldMapState RequireMap(this OnlineWorldComponent self,string mapId)
        { if(string.IsNullOrWhiteSpace(mapId)||!self.MapStates.TryGetValue(mapId,out OnlineWorldMapState state))throw new RpcException(ErrorCode.ERR_OnlineWorldOperationInvalid,$"invalid online world map: {mapId??"<null>"}");return state; }

        public static OnlineWorldSnapshot Enter(this OnlineWorldComponent self,long playerId,string displayName,ActorId playerActorId,string mapId,OnlineInventoryInfo inventoryMessage)
        {
            OnlineWorldMapState state=self.RequireMap(mapId);
            OnlineInventoryRecord incoming=self.CopyAndValidateInventory(inventoryMessage,playerId);
            if(self.PlayerMapIds.TryGetValue(playerId,out string currentMapId))
            {
                if(!string.Equals(currentMapId,mapId,StringComparison.Ordinal))throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"player is already in another map");
                if(!state.PlayerInventories.TryGetValue(playerId,out OnlineInventoryRecord activeInventory)||!string.Equals(OnlineInventoryRecordHelper.Fingerprint(activeInventory,true,0,string.Empty),OnlineInventoryRecordHelper.Fingerprint(incoming,true,0,string.Empty),StringComparison.Ordinal))throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"active inventory revision conflict");
                if(state.PendingRespawns.TryGetValue(playerId,out OnlineWorldPendingRespawn pending)){pending.PlayerActorId=playerActorId;return self.BuildSnapshot(state,0,playerId);}
                if(!state.PlayerUnits.TryGetValue(playerId,out long existingId)||!state.Units.TryGetValue(existingId,out OnlineWorldUnit existing))throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"player map index conflict");
                bool reconnected=existing.ConnectionState==OnlineWorldConnectionState.DisconnectedGrace;existing.PlayerActorId=playerActorId;existing.ConnectionState=OnlineWorldConnectionState.Online;if(reconnected)existing.NavigationEligible=true;self.RecomputeLease(state,reconnected?"reconnect":"enter-existing");return self.BuildSnapshot(state,existing.UnitId,playerId);
            }
            long sequence=state.NextSpawnSequence++;OnlineWorldUnit unit=new(){PlayerId=playerId,UnitId=self.AllocateUnitId(),DisplayName=displayName??string.Empty,WorldId=self.WorldId,MapId=state.MapId,PlayerConfigId=state.PlayerConfig.Id,PositionX=state.PlayerSpawn.PositionX+(sequence%4)*2f,PositionY=state.PlayerSpawn.PositionY,PositionZ=state.PlayerSpawn.PositionZ+(sequence/4)*2f,YawDegrees=state.PlayerSpawn.RotationY,ConnectionState=OnlineWorldConnectionState.Online,StateRevision=1,LifecycleRevision=1,CurrentHP=state.PlayerConfig.MaxHP,MaxHP=state.PlayerConfig.MaxHP,PlayerActorId=playerActorId};
            unit.TorsoItemId=incoming.TorsoItemId;unit.LegsItemId=incoming.LegsItemId;unit.HeadItemId=incoming.HeadItemId;unit.HandsItemId=incoming.HandsItemId;unit.FeetItemId=incoming.FeetItemId;unit.BackItemId=incoming.BackItemId;unit.ArmorItemId=incoming.ArmorItemId;state.Units.Add(unit.UnitId,unit);state.PlayerUnits.Add(playerId,unit.UnitId);state.PlayerInventories.Add(playerId,incoming);self.PlayerMapIds.Add(playerId,state.MapId);state.WorldRevision++;self.BroadcastEntered(state,unit);self.RecomputeLease(state,"enter");return self.BuildSnapshot(state,unit.UnitId,playerId);
        }

        public static OnlineWorldSnapshot GetSnapshot(this OnlineWorldComponent self,long playerId,long worldId,string mapId,long unitId)
        {OnlineWorldMapState state=self.RequireMap(mapId);if(worldId!=self.WorldId||!self.PlayerMapIds.TryGetValue(playerId,out string indexed)||!string.Equals(indexed,mapId,StringComparison.Ordinal))return null;if(unitId==0&&!state.PendingRespawns.ContainsKey(playerId))return null;if(unitId!=0&&(!state.PlayerUnits.TryGetValue(playerId,out long active)||active!=unitId))return null;return self.BuildSnapshot(state,unitId,playerId);}
        public static bool Leave(this OnlineWorldComponent self,long playerId,long worldId,string mapId,long unitId)
        {if(self.FailedLeaveCount>0){self.FailedLeaveCount--;throw new RpcException(ErrorCode.ERR_OnlineWorldServiceUnavailable,"world leave injected failure");}OnlineWorldMapState state=self.RequireMap(mapId);if(unitId==0&&worldId==self.WorldId&&self.PlayerMapIds.TryGetValue(playerId,out string indexed)&&string.Equals(indexed,mapId,StringComparison.Ordinal)&&state.PendingRespawns.Remove(playerId)){state.PlayerInventories.Remove(playerId);self.PlayerMapIds.Remove(playerId);return true;}if(!self.TryGetUnit(state,playerId,worldId,mapId,unitId,out OnlineWorldUnit unit))return false;self.TransitionPlayerDeath(state,unit,TimeInfo.Instance.ServerNow(),false);return true;}

        public static WorldPlayerInfo Report(this OnlineWorldComponent self,P2W_ReportWorldTransform request)
        {OnlineWorldMapState state=self.RequireMap(request.MapId);if(!self.TryGetUnit(state,request.PlayerId,request.WorldId,request.MapId,request.UnitId,out OnlineWorldUnit unit))throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"world identity conflict");if(!Finite(request.PositionX,request.PositionY,request.PositionZ,request.YawDegrees))throw new RpcException(ErrorCode.ERR_OnlineWorldOperationInvalid,"world pose is not finite");if(unit.IsDead||request.LifecycleRevision!=unit.LifecycleRevision)throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"world lifecycle conflict");unit.PositionX=request.PositionX;unit.PositionY=request.PositionY;unit.PositionZ=request.PositionZ;unit.YawDegrees=request.YawDegrees;unit.StateRevision++;state.WorldRevision++;self.BroadcastTransform(state,unit);return Clone(unit);}
        public static bool SetConnection(this OnlineWorldComponent self,P2W_SetWorldConnection request)
        {OnlineWorldMapState state=self.RequireMap(request.MapId);if(request.UnitId==0&&self.PlayerMapIds.TryGetValue(request.PlayerId,out string map)&&string.Equals(map,request.MapId,StringComparison.Ordinal)&&state.PendingRespawns.TryGetValue(request.PlayerId,out OnlineWorldPendingRespawn pending)){pending.PlayerActorId=request.PlayerActorId;return true;}if(!self.TryGetUnit(state,request.PlayerId,request.WorldId,request.MapId,request.UnitId,out OnlineWorldUnit unit))return false;OnlineWorldConnectionState next=request.ConnectionState==2?OnlineWorldConnectionState.DisconnectedGrace:OnlineWorldConnectionState.Online;bool reconnected=unit.ConnectionState==OnlineWorldConnectionState.DisconnectedGrace&&next==OnlineWorldConnectionState.Online;unit.PlayerActorId=request.PlayerActorId;unit.ConnectionState=next;if(reconnected)unit.NavigationEligible=true;self.RecomputeLease(state,next==OnlineWorldConnectionState.DisconnectedGrace?"disconnect":reconnected?"reconnect":"online");return true;}

        public static (bool Accepted,long WorldRevision,long LifecycleRevision) MeleeAttack(this OnlineWorldComponent self,P2W_WorldMeleeAttack request)
        {
            OnlineWorldMapState state=self.RequireMap(request.MapId);
            if(!self.TryGetUnit(state,request.PlayerId,request.WorldId,request.MapId,request.UnitId,out OnlineWorldUnit actor)){self.RejectedAttackCount++;self.RejectedAttackIdentityCount++;self.TrackInvalidInput(state,"attack-identity",request.UnitId,request.PlayerId);throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"world identity conflict");}
            if(request.LifecycleRevision!=actor.LifecycleRevision){self.RejectedAttackCount++;self.RejectedAttackLifecycleCount++;self.TrackInvalidInput(state,"attack-lifecycle",actor.UnitId,actor.PlayerId);throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"world lifecycle conflict");}
            long now=TimeInfo.Instance.ServerNow();if(actor.IsDead||actor.IsLeaving){self.RejectedAttackLifecycleCount++;self.RejectAttack(state,"attack-dead",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}if(request.AttackSequence<=actor.LastAcceptedAttackSequence){self.RejectedAttackSequenceCount++;self.RejectAttack(state,"attack-sequence",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}if(now<actor.NextMeleeAttackAt){self.RejectedAttackCooldownCount++;self.RejectAttack(state,"attack-cooldown",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}if(!Finite(request.AimX,request.AimZ)||request.AimX*request.AimX+request.AimZ*request.AimZ+(request.HasProjectileOrigin?request.AimY*request.AimY:0)<0.000001f||!state.PlayerInventories.TryGetValue(actor.PlayerId,out OnlineInventoryRecord inventory)){self.RejectedAttackInputCount++;self.RejectAttack(state,"attack-input",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}
            WeaponConfig weapon=null;bool projectile=false;if(request.WeaponItemId==0){if(inventory.Equipment.ActiveSlot!=1||inventory.Equipment.MeleeWeaponItemId!=0){self.RejectedAttackInputCount++;self.RejectAttack(state,"attack-slot",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}}else{try{weapon=ServerConfig.Instance.GetWeapon(request.WeaponItemId);}catch{self.RejectedAttackInputCount++;self.RejectAttack(state,"attack-weapon",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}projectile=weapon.WeaponKind==WeaponKind.Projectile;bool equipped=projectile?inventory.Equipment.ActiveSlot==2&&inventory.Equipment.RangedWeaponItemId==request.WeaponItemId&&OnlineInventoryRecordHelper.HeldStack(inventory).LoadedAmmo>0:weapon.WeaponKind==WeaponKind.Melee&&inventory.Equipment.ActiveSlot==1&&inventory.Equipment.MeleeWeaponItemId==request.WeaponItemId;if(!equipped){self.RejectedAttackInputCount++;self.RejectAttack(state,"attack-equipment",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}}
            if(projectile&&weapon.ProjectileConfigId=="projectile.arrow.basic")
            {
                bool accepted=self.TryAcceptProjectile(state,actor,request,weapon,inventory,now);
                if(!accepted){self.RejectedAttackInputCount++;self.RejectAttack(state,"projectile-input",actor);}
                return(accepted,state.WorldRevision,actor.LifecycleRevision);
            }
            if(request.AimX*request.AimX+request.AimZ*request.AimZ<0.000001f){self.RejectAttack(state,"horizontal-input",actor);return(false,state.WorldRevision,actor.LifecycleRevision);}
            int damage;float range,cooldown,arc;if(request.WeaponItemId==0){damage=state.PlayerConfig.UnarmedAttackDamage;range=state.PlayerConfig.UnarmedAttackRange;cooldown=state.PlayerConfig.UnarmedAttackCooldownSeconds;arc=state.PlayerConfig.UnarmedMeleeArcDegrees;}else{damage=weapon.AttackDamage;range=weapon.AttackRange;cooldown=weapon.AttackCooldownSeconds;arc=weapon.MeleeArcDegrees;}
            float len=(float)Math.Sqrt(request.AimX*request.AimX+request.AimZ*request.AimZ);float ax=request.AimX/len,az=request.AimZ/len;actor.YawDegrees=(float)(Math.Atan2(ax,az)*180.0/Math.PI);actor.LastAcceptedAttackSequence=request.AttackSequence;actor.NextMeleeAttackAt=now+(long)(cooldown*1000);actor.StateRevision++;self.AcceptedAttackCount++;
            List<OnlineWorldEnemy> candidates;if(projectile){OnlineInventoryRecordHelper.HeldStack(inventory).LoadedAmmo--;inventory.Revision++;candidates=state.Enemies.Values.Where(e=>!e.IsDead&&InProjectilePath(actor.PositionX,actor.PositionZ,ax,az,e.PositionX,e.PositionZ,range)).OrderBy(e=>ForwardDistance(actor.PositionX,actor.PositionZ,ax,az,e.PositionX,e.PositionZ)).ThenBy(e=>e.UnitId).Take(1).ToList();self.PushInventory(state,actor.PlayerId,inventory);}else{candidates=state.Enemies.Values.Where(e=>!e.IsDead&&InArc(actor.PositionX,actor.PositionZ,ax,az,e.PositionX,e.PositionZ,range,arc)).OrderBy(e=>DistanceSquared(actor.PositionX,actor.PositionZ,e.PositionX,e.PositionZ)).ThenBy(e=>e.UnitId).ToList();if(request.WeaponItemId==0&&candidates.Count>1)candidates.RemoveRange(1,candidates.Count-1);}if(candidates.Count==0)self.AcceptedAttackWhiffCount++;foreach(OnlineWorldEnemy enemy in candidates)self.DamageEnemy(state,enemy,damage,now);state.WorldRevision++;self.BroadcastCombat(state,projectile?3:1,actor.UnitId,request.WeaponItemId,new[]{actor},candidates);if(projectile&&candidates.Count==0){ProjectileConfig projectileConfig=ServerConfig.Instance.GetProjectile(weapon.ProjectileConfigId);self.CreateProjectileRecovery(state,projectileConfig.RecoveryLootConfigId,actor.PositionX+ax*projectileConfig.MaxTravelDistance,actor.PositionY,actor.PositionZ+az*projectileConfig.MaxTravelDistance,actor.YawDegrees,now);}if(candidates.Any(x=>x.IsDead))self.RecomputeLease(state,"enemy-death");return(true,state.WorldRevision,actor.LifecycleRevision);
        }

        public static (bool Accepted,long LeaseRevision,long LastSequence,long WorldRevision) ReportNavigation(this OnlineWorldComponent self,P2W_ReportWorldEnemyNavigation request)
        {
            OnlineWorldMapState state=self.RequireMap(request.MapId);if(!self.TryGetUnit(state,request.PlayerId,request.WorldId,request.MapId,request.UnitId,out OnlineWorldUnit actor))throw new RpcException(ErrorCode.ERR_OnlineWorldStateConflict,"world identity conflict");if(state.Enemies.Count==0)return(false,0,0,state.WorldRevision);
            if(actor.ConnectionState!=OnlineWorldConnectionState.Online||actor.UnitId!=state.NavigationExecutorUnitId||request.NavigationLeaseRevision!=state.NavigationLeaseRevision){self.RejectedOldLeaseCount++;self.TrackInvalidInput(state,"navigation-lease",actor.UnitId,actor.PlayerId);return(false,state.NavigationLeaseRevision,state.LastAcceptedNavigationReportSequence,state.WorldRevision);}if(request.ReportSequence<=state.LastAcceptedNavigationReportSequence){self.RejectedNavigationSequenceCount++;self.TrackInvalidInput(state,"navigation-sequence",actor.UnitId,actor.PlayerId);return(false,state.NavigationLeaseRevision,state.LastAcceptedNavigationReportSequence,state.WorldRevision);}
            long now=TimeInfo.Instance.ServerNow();state.LastAcceptedNavigationReportSequence=request.ReportSequence;state.LastNavigationHeartbeatAt=now;List<OnlineWorldEnemy> changed=new();foreach(WorldEnemyNavigationReport report in request.Reports){if(!state.Enemies.TryGetValue(report.UnitId,out OnlineWorldEnemy enemy)||enemy.IsDead||report.LifecycleRevision!=enemy.LifecycleRevision)continue;if(!Finite(report.PositionX,report.PositionY,report.PositionZ,report.YawDegrees)){self.RejectedNavigationFloatCount++;self.TrackInvalidInput(state,"navigation-float",report.UnitId,actor.PlayerId);continue;}float seconds=Math.Max((now-enemy.LastNavigationAt)/1000f,0.1f);float limit=enemy.Config.MoveSpeed*seconds*3f+1f;if(Math.Abs(report.PositionY-enemy.PositionY)>3f||DistanceSquared(enemy.PositionX,enemy.PositionZ,report.PositionX,report.PositionZ)>limit*limit){self.RejectedNavigationRangeCount++;self.TrackInvalidInput(state,"navigation-range",enemy.UnitId,actor.PlayerId);continue;}bool moved=report.PositionX!=enemy.PositionX||report.PositionY!=enemy.PositionY||report.PositionZ!=enemy.PositionZ||report.YawDegrees!=enemy.YawDegrees;enemy.LastNavigationAt=now;if(!moved)continue;enemy.PositionX=report.PositionX;enemy.PositionY=report.PositionY;enemy.PositionZ=report.PositionZ;enemy.YawDegrees=report.YawDegrees;enemy.StateRevision++;changed.Add(enemy);}if(changed.Count>0){state.WorldRevision++;self.BroadcastEnemyTransforms(state,changed);}return(true,state.NavigationLeaseRevision,state.LastAcceptedNavigationReportSequence,state.WorldRevision);
        }

        private static async ETTask TickLoop(OnlineWorldComponent self,int generation){while(!self.IsDisposed&&self.TickGeneration==generation){await self.Root().GetComponent<TimerComponent>().WaitAsync(self.TickMilliseconds);if(self.IsDisposed||self.TickGeneration!=generation)return;self.Tick(TimeInfo.Instance.ServerNow());}}
        public static void Tick(this OnlineWorldComponent self,long now)
        {
            foreach(OnlineWorldMapState state in self.MapStates.Values)
            {
                self.TickProjectiles(state,now);
                if(state.Enemies.Count>0&&state.NavigationExecutorUnitId!=0&&now-state.LastNavigationHeartbeatAt>self.NavigationLeaseTimeoutMilliseconds)self.RecomputeLease(state,"heartbeat-timeout",true);List<OnlineWorldUnit> changedPlayers=new();List<OnlineWorldEnemy> changedEnemies=new();
                self.RespawnPendingPlayers(state,now);self.CleanupCorpses(state,now);
                foreach(OnlineWorldEnemy e in state.Enemies.Values){OnlineWorldUnit target=state.Units.Values.Where(p=>!p.IsDead).OrderBy(p=>DistanceSquared(e.PositionX,e.PositionZ,p.PositionX,p.PositionZ)).ThenBy(p=>p.UnitId).FirstOrDefault();long targetId=target?.UnitId??0;if(targetId!=e.TargetUnitId){e.TargetUnitId=targetId;e.StateRevision++;changedEnemies.Add(e);}if(target!=null&&now>=e.NextAttackAt&&DistanceSquared(e.PositionX,e.PositionZ,target.PositionX,target.PositionZ)<=e.Config.AttackRange*e.Config.AttackRange){e.NextAttackAt=now+(long)(e.Config.AttackCooldownSeconds*1000);long damagedId=target.UnitId;self.DamagePlayer(state,target,e.Config.AttackDamage,now);state.WorldRevision++;self.BroadcastCombat(state,2,e.UnitId,0,state.Units.ContainsKey(damagedId)?new[]{target}:Array.Empty<OnlineWorldUnit>(),new[]{e});}}
                if(changedPlayers.Count>0||changedEnemies.Count>0){state.WorldRevision++;self.BroadcastCombat(state,0,0,0,changedPlayers,changedEnemies);}
            }
        }
        private static void DamagePlayer(this OnlineWorldComponent self,OnlineWorldMapState state,OnlineWorldUnit p,int damage,long now){if(p.IsDead)return;int next=Math.Max(0,p.CurrentHP-damage);if(next==0){p.CurrentHP=0;p.StateRevision++;p.LifecycleRevision++;self.PlayerDeathCount++;self.TransitionPlayerDeath(state,p,now,true);Log.Info($"online world player death worldId={self.WorldId} mapId={state.MapId} unitId={p.UnitId} playerId={p.PlayerId}");return;}p.CurrentHP=next;p.StateRevision++;}
        public static void DamageEnemy(this OnlineWorldComponent self,OnlineWorldMapState state,OnlineWorldEnemy e,int damage,long now){if(e.IsDead)return;int next=Math.Max(0,e.CurrentHP-damage);if(next==0)self.CreateEnemyCorpse(state,e,now);e.CurrentHP=next;e.StateRevision++;if(e.CurrentHP==0){e.IsDead=true;e.TargetUnitId=0;e.LifecycleRevision++;state.Enemies.Remove(e.UnitId);self.EnemyDeathCount++;Log.Info($"online world enemy death worldId={self.WorldId} mapId={state.MapId} unitId={e.UnitId} lifecycle={e.LifecycleRevision}");}}
        private static void RecomputeLease(this OnlineWorldComponent self,OnlineWorldMapState state,string reason,bool renewExpired=false){if(state.Enemies.Count==0){if(state.NavigationExecutorUnitId==0)return;state.NavigationExecutorUnitId=0;state.NavigationLeaseRevision++;state.LastAcceptedNavigationReportSequence=0;state.LastNavigationHeartbeatAt=TimeInfo.Instance.ServerNow();state.WorldRevision++;self.LeaseTransferCount++;self.BroadcastLease(state);Log.Info($"online world navigation lease worldId={self.WorldId} mapId={state.MapId} executor=0 revision={state.NavigationLeaseRevision} reason={reason}");return;}if(renewExpired&&state.Units.TryGetValue(state.NavigationExecutorUnitId,out OnlineWorldUnit expired)&&expired.NavigationEligible&&state.Units.Values.Any(x=>x.UnitId!=expired.UnitId&&x.NavigationEligible&&x.ConnectionState==OnlineWorldConnectionState.Online&&x.PlayerActorId!=default))expired.NavigationEligible=false;List<long> eligible=state.Units.Values.Where(x=>x.NavigationEligible&&x.ConnectionState==OnlineWorldConnectionState.Online&&x.PlayerActorId!=default&&!x.IsLeaving).Select(x=>x.UnitId).OrderBy(x=>x).ToList();long next=eligible.Count==0?0:eligible[0];if(next==state.NavigationExecutorUnitId&&!renewExpired)return;state.NavigationExecutorUnitId=next;state.NavigationLeaseRevision++;state.LastAcceptedNavigationReportSequence=0;state.LastNavigationHeartbeatAt=TimeInfo.Instance.ServerNow();state.WorldRevision++;self.LeaseTransferCount++;self.BroadcastLease(state);Log.Info($"online world navigation lease worldId={self.WorldId} mapId={state.MapId} executor={next} revision={state.NavigationLeaseRevision} reason={reason}");}
        public static void RecomputeLeaseForInventory(this OnlineWorldComponent self,OnlineWorldMapState state,string reason)=>self.RecomputeLease(state,reason);
        private static void RejectAttack(this OnlineWorldComponent self,OnlineWorldMapState state,string reason,OnlineWorldUnit actor){self.RejectedAttackCount++;self.TrackInvalidInput(state,reason,actor.UnitId,actor.PlayerId);}
        private static void TrackInvalidInput(this OnlineWorldComponent self,OnlineWorldMapState state,string reason,long unitId,long playerId){self.InvalidInputSinceLastLog++;long now=TimeInfo.Instance.ServerNow();if(self.InvalidInputSinceLastLog<10&&now-self.LastInvalidInputLogAt<5000)return;Log.Warning($"online world invalid input worldId={self.WorldId} mapId={state?.MapId} unitId={unitId} playerId={playerId} reason={reason} count={self.InvalidInputSinceLastLog} diagnostics='{self.BuildDiagnostics()}'");self.InvalidInputSinceLastLog=0;self.LastInvalidInputLogAt=now;}
        public static string BuildDiagnostics(this OnlineWorldComponent self){int players=self.MapStates.Values.Sum(s=>s.Units.Count),alivePlayers=self.MapStates.Values.Sum(s=>s.Units.Values.Count(x=>!x.IsDead)),enemies=self.MapStates.Values.Sum(s=>s.Enemies.Count);return $"maps={self.MapStates.Count},players={players},alivePlayers={alivePlayers},deadPlayers={players-alivePlayers},enemies={enemies},leaseTransfers={self.LeaseTransferCount},attacksAccepted={self.AcceptedAttackCount},attackWhiffs={self.AcceptedAttackWhiffCount},attackRejected={self.RejectedAttackCount},identity={self.RejectedAttackIdentityCount},lifecycle={self.RejectedAttackLifecycleCount},sequence={self.RejectedAttackSequenceCount},cooldown={self.RejectedAttackCooldownCount},input={self.RejectedAttackInputCount},playerDeaths={self.PlayerDeathCount},playerRespawns={self.PlayerRespawnCount},enemyDeaths={self.EnemyDeathCount},oldLease={self.RejectedOldLeaseCount},navSequence={self.RejectedNavigationSequenceCount},navFloat={self.RejectedNavigationFloatCount},navRange={self.RejectedNavigationRangeCount}";}
        private static bool TryGetUnit(this OnlineWorldComponent self,OnlineWorldMapState state,long playerId,long worldId,string mapId,long unitId,out OnlineWorldUnit unit){unit=null;return worldId==self.WorldId&&string.Equals(mapId,state.MapId,StringComparison.Ordinal)&&self.PlayerMapIds.TryGetValue(playerId,out string indexedMap)&&string.Equals(indexedMap,state.MapId,StringComparison.Ordinal)&&state.PlayerUnits.TryGetValue(playerId,out long indexedUnit)&&indexedUnit==unitId&&state.Units.TryGetValue(unitId,out unit);}
        private static bool Finite(params float[] values){foreach(float value in values)if(float.IsNaN(value)||float.IsInfinity(value))return false;return true;}
        private static float DistanceSquared(float ax,float az,float bx,float bz){float x=bx-ax,z=bz-az;return x*x+z*z;}
        private static float ForwardDistance(float ox,float oz,float ax,float az,float tx,float tz)=>ax*(tx-ox)+az*(tz-oz);
        private static bool InProjectilePath(float ox,float oz,float ax,float az,float tx,float tz,float range){float dx=tx-ox,dz=tz-oz;float forward=ax*dx+az*dz;if(forward<0f||forward>range)return false;float lateralSquared=dx*dx+dz*dz-forward*forward;return lateralSquared<=0.75f*0.75f;}
        private static bool InArc(float ox,float oz,float ax,float az,float tx,float tz,float range,float arc){float dx=tx-ox,dz=tz-oz,d2=dx*dx+dz*dz;if(d2>range*range)return false;if(d2<0.000001f)return true;float dot=(ax*dx+az*dz)/(float)Math.Sqrt(d2);return dot>=Math.Cos(arc*0.5*Math.PI/180.0);}
        private static OnlineWorldSnapshot BuildSnapshot(this OnlineWorldComponent self,OnlineWorldMapState state,long selfId,long playerId){OnlineWorldSnapshot s=OnlineWorldSnapshot.Create();s.WorldId=self.WorldId;s.MapId=state.MapId;s.WorldRevision=state.WorldRevision;s.SelfUnitId=selfId;s.NavigationExecutorUnitId=state.NavigationExecutorUnitId;s.NavigationLeaseRevision=state.NavigationLeaseRevision;s.ServerTime=TimeInfo.Instance.ServerNow();if(self.EnsureCollisionData(state))s.CollisionContentHash=state.CollisionData.ContentHash;foreach(var arrow in state.Projectiles.Values.OrderBy(p=>p.RuntimeId))s.Projectiles.Add(OnlineWorldProjectileMessages.ProjectileMessage(arrow));if(state.PlayerInventories.TryGetValue(playerId,out OnlineInventoryRecord inventory))s.SelfInventory=OnlineWorldInventorySystem.InventoryMessage(inventory);foreach(OnlineWorldUnit p in state.Units.Values.OrderBy(x=>x.UnitId))s.Players.Add(Clone(p));foreach(OnlineWorldEnemy e in state.Enemies.Values.OrderBy(x=>x.UnitId))s.Enemies.Add(Clone(e));foreach(OnlineWorldCorpse c in state.Corpses.Values.OrderBy(x=>x.CorpseId))s.Corpses.Add(OnlineWorldInventorySystem.CorpseMessage(c));foreach(OnlineWorldTemporaryBuilding b in state.TemporaryBuildings.Values.OrderBy(x=>x.RuntimeId))s.TemporaryBuildings.Add(TemporaryBuildingMessage(b));return s;}

        private static WorldTemporaryBuildingInfo TemporaryBuildingMessage(OnlineWorldTemporaryBuilding value)
        {
            WorldTemporaryBuildingInfo message = WorldTemporaryBuildingInfo.Create();
            message.RuntimeId = value.RuntimeId; message.ConfigId = value.ConfigId; message.WorldId = value.WorldId; message.MapId = value.MapId;
            message.PositionX = value.PositionX; message.PositionY = value.PositionY; message.PositionZ = value.PositionZ; message.YawDegrees = value.YawDegrees;
            message.LoadedAmmo = value.LoadedAmmo; message.NextShootAtServerTime = value.NextShootAtServerTime; message.StateRevision = value.StateRevision;
            return message;
        }
        public static WorldPlayerInfo Clone(OnlineWorldUnit p){WorldPlayerInfo i=WorldPlayerInfo.Create();i.TorsoItemId=p.TorsoItemId;i.LegsItemId=p.LegsItemId;i.HeadItemId=p.HeadItemId;i.HandsItemId=p.HandsItemId;i.FeetItemId=p.FeetItemId;i.BackItemId=p.BackItemId;i.ArmorItemId=p.ArmorItemId;i.PlayerId=p.PlayerId;i.UnitId=p.UnitId;i.DisplayName=p.DisplayName;i.WorldId=p.WorldId;i.MapId=p.MapId;i.PlayerConfigId=p.PlayerConfigId;i.PositionX=p.PositionX;i.PositionY=p.PositionY;i.PositionZ=p.PositionZ;i.YawDegrees=p.YawDegrees;i.ConnectionState=(int)p.ConnectionState;i.StateRevision=p.StateRevision;i.CurrentHP=p.CurrentHP;i.MaxHP=p.MaxHP;i.IsDead=p.IsDead;i.RespawnAtServerTime=p.RespawnAtServerTime;i.LastAcceptedAttackSequence=p.LastAcceptedAttackSequence;i.LifecycleRevision=p.LifecycleRevision;return i;}
        public static WorldEnemyInfo Clone(OnlineWorldEnemy e){WorldEnemyInfo i=WorldEnemyInfo.Create();i.UnitId=e.UnitId;i.WorldId=e.WorldId;i.MapId=e.MapId;i.EnemyConfigId=e.EnemyConfigId;i.SpawnPositionX=e.SpawnPositionX;i.SpawnPositionY=e.SpawnPositionY;i.SpawnPositionZ=e.SpawnPositionZ;i.SpawnYawDegrees=e.SpawnYawDegrees;i.PositionX=e.PositionX;i.PositionY=e.PositionY;i.PositionZ=e.PositionZ;i.YawDegrees=e.YawDegrees;i.TargetUnitId=e.TargetUnitId;i.CurrentHP=e.CurrentHP;i.MaxHP=e.MaxHP;i.IsDead=e.IsDead;i.RespawnAtServerTime=0;i.StateRevision=e.StateRevision;i.LifecycleRevision=e.LifecycleRevision;return i;}
        private static IEnumerable<OnlineWorldUnit> OnlineTargets(OnlineWorldMapState state)=>state.Units.Values.Where(x=>x.ConnectionState==OnlineWorldConnectionState.Online&&x.PlayerActorId!=default);
        private static void BroadcastEntered(this OnlineWorldComponent self,OnlineWorldMapState state,OnlineWorldUnit entered){foreach(OnlineWorldUnit t in OnlineTargets(state).Where(x=>x.UnitId!=entered.UnitId)){W2P_WorldPlayerEntered m=W2P_WorldPlayerEntered.Create();m.PlayerId=t.PlayerId;m.WorldRevision=state.WorldRevision;m.Player=Clone(entered);self.Root().GetComponent<MessageSender>().Send(t.PlayerActorId,m);}}
        private static void BroadcastTransform(this OnlineWorldComponent self,OnlineWorldMapState state,OnlineWorldUnit p){foreach(OnlineWorldUnit t in OnlineTargets(state).Where(x=>x.UnitId!=p.UnitId)){W2P_WorldPlayerTransformChanged m=W2P_WorldPlayerTransformChanged.Create();m.PlayerId=t.PlayerId;m.WorldId=self.WorldId;m.MapId=state.MapId;m.WorldRevision=state.WorldRevision;m.Player=Clone(p);self.Root().GetComponent<MessageSender>().Send(t.PlayerActorId,m);}}
        private static void BroadcastLeft(this OnlineWorldComponent self,OnlineWorldMapState state,long id){foreach(OnlineWorldUnit t in OnlineTargets(state)){W2P_WorldPlayerLeft m=W2P_WorldPlayerLeft.Create();m.PlayerId=t.PlayerId;m.WorldId=self.WorldId;m.MapId=state.MapId;m.WorldRevision=state.WorldRevision;m.UnitId=id;self.Root().GetComponent<MessageSender>().Send(t.PlayerActorId,m);}}
        public static void BroadcastCombat(this OnlineWorldComponent self,OnlineWorldMapState state,int kind,long actor,int weapon,IEnumerable<OnlineWorldUnit> players,IEnumerable<OnlineWorldEnemy> enemies){List<OnlineWorldUnit> ps=players.Distinct().ToList();List<OnlineWorldEnemy> es=enemies.Distinct().ToList();long seq=++state.CombatSequence;foreach(OnlineWorldUnit t in OnlineTargets(state)){W2P_WorldCombatChanged m=W2P_WorldCombatChanged.Create();m.PlayerId=t.PlayerId;m.WorldId=self.WorldId;m.MapId=state.MapId;m.WorldRevision=state.WorldRevision;m.ServerTime=TimeInfo.Instance.ServerNow();m.CombatSequence=seq;m.ActionKind=kind;m.ActorUnitId=actor;m.WeaponItemId=weapon;foreach(OnlineWorldEnemy e in es)m.TargetUnitIds.Add(e.UnitId);foreach(OnlineWorldUnit p in ps)m.Players.Add(Clone(p));foreach(OnlineWorldEnemy e in es)m.Enemies.Add(Clone(e));self.Root().GetComponent<MessageSender>().Send(t.PlayerActorId,m);}}
        private static void BroadcastEnemyTransforms(this OnlineWorldComponent self,OnlineWorldMapState state,IEnumerable<OnlineWorldEnemy> enemies){List<OnlineWorldEnemy> list=enemies.ToList();foreach(OnlineWorldUnit t in OnlineTargets(state)){W2P_WorldEnemiesTransformChanged m=W2P_WorldEnemiesTransformChanged.Create();m.PlayerId=t.PlayerId;m.WorldId=self.WorldId;m.MapId=state.MapId;m.WorldRevision=state.WorldRevision;foreach(OnlineWorldEnemy e in list){WorldEnemyTransformInfo i=WorldEnemyTransformInfo.Create();i.UnitId=e.UnitId;i.PositionX=e.PositionX;i.PositionY=e.PositionY;i.PositionZ=e.PositionZ;i.YawDegrees=e.YawDegrees;i.StateRevision=e.StateRevision;i.LifecycleRevision=e.LifecycleRevision;m.Enemies.Add(i);}self.Root().GetComponent<MessageSender>().Send(t.PlayerActorId,m);}}
        private static void BroadcastLease(this OnlineWorldComponent self,OnlineWorldMapState state){foreach(OnlineWorldUnit t in OnlineTargets(state)){W2P_WorldNavigationLeaseChanged m=W2P_WorldNavigationLeaseChanged.Create();m.PlayerId=t.PlayerId;m.WorldId=self.WorldId;m.MapId=state.MapId;m.WorldRevision=state.WorldRevision;m.NavigationExecutorUnitId=state.NavigationExecutorUnitId;m.NavigationLeaseRevision=state.NavigationLeaseRevision;m.ServerTime=TimeInfo.Instance.ServerNow();self.Root().GetComponent<MessageSender>().Send(t.PlayerActorId,m);}}
    }
}
